UPDATE lessons SET title = 'Consonant Sound Review', description = 'Review consonant sounds b, k, d, f, g, h, j, l, m, n, p, r, s', vocabulary = '[{"word":"ball","phonetic":"/b/","meaning":"/b/ sound"},{"word":"cat","phonetic":"/k/","meaning":"/k/ sound"},{"word":"dog","phonetic":"/d/","meaning":"/d/ sound"},{"word":"fish","phonetic":"/f/","meaning":"/f/ sound"},{"word":"lion","phonetic":"/l/","meaning":"/l/ sound"}]'::jsonb, sentences = '[{"text":"Say each consonant sound","tip":"Listen carefully"},{"text":"Match the sound to the word","tip":"You know these!"}]'::jsonb, read_aloud_text = 'Amazing! You have learned so many consonant sounds! Let us review them all!' WHERE level = 'beginner' AND day_number = 29;

UPDATE lessons SET title = 'Phase 1 Mastery Gate', description = 'Complete the Sound Awareness mastery challenge to unlock Phase 2!', vocabulary = '[{"word":"apple","phonetic":"/æ/","meaning":"Vowel /a/"},{"word":"ball","phonetic":"/b/","meaning":"Consonant /b/"},{"word":"cat","phonetic":"/k/","meaning":"Consonant /k/"},{"word":"dog","phonetic":"/d/","meaning":"Consonant /d/"},{"word":"elephant","phonetic":"/ɛ/","meaning":"Vowel /e/"}]'::jsonb, sentences = '[{"text":"I know all my sounds","tip":"You are a sound champion!"},{"text":"Ready for the next adventure","tip":"Phase 2 awaits!"}]'::jsonb, read_aloud_text = 'You have completed Phase 1: Sound Awareness! You are a phonics superstar! Get ready for Phase 2!' WHERE level = 'beginner' AND day_number = 30;
